do $$
declare n int;
begin
  select (select count(*) from public.opening_lines    r where r::text ~* '(^|[^a-zăâîşţșț])(apasă|apăsa|apăsând)')
       + (select count(*) from public.middlegame_plans r where r::text ~* '(^|[^a-zăâîşţșț])(apasă|apăsa|apăsând)')
       + (select count(*) from public.opening_traps    r where r::text ~* '(^|[^a-zăâîşţșț])(apasă|apăsa|apăsând)')
  into n;
  if n > 0 then
    raise exception 'Mai sunt % rânduri cu „apasă"', n;
  end if;
end $$;
